<?php
require_once __DIR__ . '/includes/functions.php';
$stmt=db()->prepare("SELECT bp.*,bc.name AS category_name FROM blog_posts bp LEFT JOIN blog_categories bc ON bc.id=bp.category_id WHERE bp.slug=? AND bp.status='published' AND bp.published_at<=NOW() LIMIT 1");$stmt->execute([trim((string)($_GET['slug']??''))]);$post=$stmt->fetch();
if(!$post){http_response_code(404);$pageTitle='Story not found | Yucca Fabrics';require __DIR__.'/includes/header.php';echo '<section class="mx-auto max-w-3xl px-5 py-24 text-center"><h1 class="font-serif text-4xl">Story not found</h1><a class="mt-6 inline-block underline" href="'.e(url('blog.php')).'">Back to the journal</a></section>';require __DIR__.'/includes/footer.php';exit;}
$pageTitle=$post['title'].' | Yucca Fabrics';$description=$post['excerpt']?:$post['title'];$structuredData=['@context'=>'https://schema.org','@type'=>'Article','headline'=>$post['title'],'datePublished'=>$post['published_at'],'description'=>$description,'mainEntityOfPage'=>absolute_url('article.php?slug='.rawurlencode($post['slug']))];require __DIR__.'/includes/header.php';
?>
<article class="mx-auto max-w-3xl px-5 py-12"><a class="text-sm underline" href="<?= e(url('blog.php')) ?>">← The journal</a><p class="eyebrow mt-8"><?= e($post['category_name']??'Yucca notes') ?> · <?= e(date('F j, Y',strtotime($post['published_at']))) ?></p><h1 class="mt-3 font-serif text-4xl leading-tight sm:text-5xl"><?= e($post['title']) ?></h1><?php if($post['image']): ?><img class="mt-8 max-h-[560px] w-full object-cover" src="<?= e(url('uploads/blog/'.rawurlencode(basename($post['image'])))) ?>" alt="<?= e($post['title']) ?>"><?php endif; ?><div class="prose mt-8 max-w-none whitespace-pre-line text-base leading-8 text-gray-700"><?= e($post['body']) ?></div><div class="mt-10 border-t border-black/10 pt-5 text-sm"><span>Share this story:</span> <a class="ml-3 underline" href="https://www.facebook.com/sharer/sharer.php?u=<?= e(rawurlencode(absolute_url('article.php?slug='.$post['slug']))) ?>" target="_blank" rel="noopener">Facebook</a> <a class="ml-3 underline" href="https://wa.me/?text=<?= e(rawurlencode($post['title'].' '.absolute_url('article.php?slug='.$post['slug']))) ?>" target="_blank" rel="noopener">WhatsApp</a></div></article>
<?php require __DIR__ . '/includes/footer.php'; ?>
